    public static class MeisselLehmer2 {
        int[] primes;
        int[] xcums;
        long[] isp;
        int cachelimit;
        HashMap<Long, Long> picache;
        int[][] cumps;
        int[] FP = { 2, 3, 5, 7, 11, 13, 17, 19 };
        int M = FP.length;
        int B = 100;

        public MeisselLehmer2(long n) {
            assert n >= 4;
            picache = new HashMap<>();

            int s = (int) Math.sqrt(n) * B;
            cachelimit = s;
            this.primes = sieveEratosthenes(s);
            xcums = new int[(s >>> 6) + 1];
            isp = new long[(s >>> 6) + 1];
            for (int p : primes)
                isp[p >>> 6] |= 1L << p;
            for (int i = 0; i < xcums.length - 1; i++)
                xcums[i + 1] = xcums[i] + Long.bitCount(isp[i]);

            cumps = new int[M][];
            boolean[] b = { true };
            int len = 1;
            for (int i = 0; i < M; i++) {
                len *= FP[i];
                boolean[] c = new boolean[len];
                for (int j = 0; j < FP[i]; j++) {
                    System.arraycopy(b, 0, c, j * b.length, b.length);
                }
                for (int k = 0; k < len; k += FP[i])
                    c[k] = false;
                cumps[i] = new int[len + 1];
                for (int j = 0; j < len; j++)
                    cumps[i][j + 1] = cumps[i][j] + (c[j] ? 1 : 0);
                FP[i] = len;
                b = c;
